import{_ as s}from"./chunks/astrometrics.DNqhQYp4.js";import{_ as r,C as o,o as i,c as n,a6 as e,E as d}from"./chunks/framework.DIp0zHSV.js";const w=JSON.parse('{"title":"Astrometrics","description":"The LCARdS Astrometrics card (custom:lcards-astrometrics-card): 3D scenes in the style of the astrometrics lab and stellar cartography. Sector maps, galaxy discs, sky domes with the sun and moon, labelled points you tap to fly to.","frontmatter":{"description":"The LCARdS Astrometrics card (custom:lcards-astrometrics-card): 3D scenes in the style of the astrometrics lab and stellar cartography. Sector maps, galaxy discs, sky domes with the sun and moon, labelled points you tap to fly to."},"headers":[],"relativePath":"cards/astrometrics/index.md","filePath":"cards/astrometrics/index.md","lastUpdated":1794148291000}'),l={name:"cards/astrometrics/index.md"};function c(h,t,m,p,u,y){const a=o("AstroScaleDiagram");return i(),n("div",null,[t[0]||(t[0]=e('<h1 id="astrometrics" tabindex="-1">Astrometrics <a class="header-anchor" href="#astrometrics" aria-label="Permalink to &quot;Astrometrics&quot;">​</a></h1><p><code>custom:lcards-astrometrics-card</code></p><p><img src="'+s+'" alt="Astrometrics card: a galaxy disc with bearing labels round its rim, the galactic core glowing yellow, Federation space as a blue see-through sector, Borg space as a green one, crossing beams and a small blue planet with its orbits"></p><p><strong>A 3D scene in the style of the astrometrics lab and stellar cartography: a lettered sector map, a galaxy disc with territories, a planet with an away team on it, or the sky over your home with the sun and moon where they are now.</strong> Drag to orbit, scroll or pinch to zoom, and tap a point to fly to it.</p><ul><li><strong>Objects</strong> draw the scene (grids, planets, territories, routes, nebulas, ships), and <strong>points</strong> are the named places on it that labels, routes and the camera refer to by id.</li><li>The camera orbits a target, and named views let a tap fly it from the galaxy to a planet and back.</li><li>The scene draws only when something moves, so an idle card costs nothing, and every astrometrics card and WebGL background on a page shares one WebGL context.</li></ul><div class="tip custom-block"><p class="custom-block-title">Try it</p><ul><li>The card editor opens the <a href="./start.html#the-studio">Astrometrics Studio</a>: a full-screen editor with the live scene, where you tap, drag and place points, edit every object in a form, capture camera views and start from a starter.</li><li><a href="./start.html">Getting Started</a> has a first card to copy and every starter with its picture.</li></ul></div><h2 id="how-a-scene-is-sized" tabindex="-1">How a scene is sized <a class="header-anchor" href="#how-a-scene-is-sized" aria-label="Permalink to &quot;How a scene is sized&quot;">​</a></h2><p><strong>One card holds one scene, and every position, size and distance in it is in scene units: your own, or real ones you name.</strong> Most scenes are built to fit; a true-scale scene uses the real numbers and can reach from a galaxy down to a station.</p><ul><li><strong>Scene units</strong> are yours to pick: a disc of radius 100, planets 5 across. Nothing is to scale, and everything shows at once. This is the easy way, and most starters work like this.</li><li><strong>Named units</strong> (<code>units: ly</code>, <code>pc</code>, <code>au</code>, <code>km</code> or <code>m</code> on the card) say what one unit is, so real numbers come out right: a galaxy 100,000 light years across, a planet at its real distance, a model at its real size (a model&#39;s <code>length</code> is in metres and is converted to the scene&#39;s units).</li><li><strong>A star system</strong> (a <code>system</code> object placed at one of the scene&#39;s points) is a scene inside the scene, with units of its own: a galaxy in light years holds a solar system in km. As the camera flies close it switches to the system&#39;s units, so one card spans the whole range.</li><li><strong>Screen sizes</strong> (line widths, dashes, label and marker sizes) are in px, the same at any zoom. Every other length (<code>radius</code>, <code>size</code>, <code>line_spacing</code>, positions) is in scene units.</li></ul>',9)),d(a),t[1]||(t[1]=e('<p><a href="./scale.html">Scale</a> has the details: units, star systems, the real Solar System and the scene clock.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><p><strong>Pick the starter closest to what you want and change it; it is quicker than an empty scene.</strong> The Studio&#39;s Starters tab adds one with a few settings, and <a href="./start.html#starters">Getting Started</a> shows them all with pictures.</p><table tabindex="0"><thead><tr><th>You want</th><th>Start with</th></tr></thead><tbody><tr><td>A galaxy map with territories</td><td><a href="./starters.html#galaxy-with-territories">Galaxy with territories</a> (scene units), <a href="./starters.html#federation-map">Federation map</a> (scene units), <a href="./starters.html#star-trek-galaxy">Star Trek galaxy</a> (ly)</td></tr><tr><td>A sector map or tactical grid</td><td><a href="./starters.html#sector-map">Sector map</a> (scene units)</td></tr><tr><td>Planets and orbits</td><td><a href="./starters.html#solar-system">Solar system</a> (scene units), <a href="./starters.html#solar-system-real-positions">Solar system (real positions)</a> (km, the planets where they are on the scene clock&#39;s date)</td></tr><tr><td>The sky over your home</td><td><a href="./starters.html#sky-dome-the-sun-and-moon">Sky dome: the sun and moon</a> (scene units; the sun and moon where they are now, from your Home Assistant location)</td></tr><tr><td>A ship or starbase close up</td><td><a href="./starters.html#starbase-approach">Starbase approach</a>, <a href="./starters.html#deep-space-9">Deep Space 9</a>, <a href="./starters.html#utopia-planitia-yards">Utopia Planitia yards</a>, <a href="./starters.html#borg-encounter">Borg encounter</a> (scene units)</td></tr><tr><td>From a galaxy down to a station</td><td><a href="./starters.html#galaxy-to-station-at-true-scale">Galaxy to station at true scale</a> (ly, with a solar system in km inside)</td></tr><tr><td>Something of your own</td><td>The <a href="./start.html#quick-start">quick start</a>: a grid and a few points (scene units)</td></tr></tbody></table><h2 id="pages" tabindex="-1">Pages <a class="header-anchor" href="#pages" aria-label="Permalink to &quot;Pages&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Covers</th></tr></thead><tbody><tr><td><a href="./start.html">Getting Started</a></td><td>A first card, the starters with pictures, and the card&#39;s own options</td></tr><tr><td><a href="./starters.html">Starters</a></td><td>Every ready-made scene and part as a live card with its YAML</td></tr><tr><td><a href="./points.html">Points</a></td><td>Named places: where they sit, labels, markers, actions, cards pinned to them</td></tr><tr><td><a href="./objects.html">Objects</a></td><td>Which object type to use for what, and the keys every object takes</td></tr><tr><td><a href="./camera.html">Camera and Views</a></td><td>Named views, controls, the on-card buttons, following a point, limits</td></tr><tr><td><a href="./scene.html">Scene and Looks</a></td><td>Units and motion, the diagram and realistic looks, stars, background, labels</td></tr><tr><td><a href="./data.html">Live Data</a></td><td>Points and settings that follow entities, templates, rules, a guided tour</td></tr><tr><td><a href="./effects.html">Effects</a></td><td>Nebulas, scan bands, moving dashes, animated fills, warp and dust</td></tr><tr><td><a href="./scale.html">Scale</a></td><td>Real units, star systems in their own units, the real Solar System and the scene clock</td></tr><tr><td><a href="./models.html">Your Own Models</a></td><td>Ships and stations from your own glTF files</td></tr></tbody></table>',6))])}const b=r(l,[["render",c]]);export{w as __pageData,b as default};
